    /** Writes the ROLLUP and TOTALS lines for the figures the change moved since {@code before}. */
    public void record(String sheetId, String by, RollupBefore before) {
        Map<Long, Figures> after = take(sheetId).figures();
        for (Map.Entry<Long, Figures> e : after.entrySet()) {
            Figures was = before.figures().get(e.getKey());
            Figures now = e.getValue();
            if (was == null || !was.claimed().equals(now.claimed()) || !was.dueTotal().equals(now.dueTotal())
                    || !was.overdueTotal().equals(now.overdueTotal())) {
                audit.record("ROLLUP sheet=" + sheetId + " by=" + by + " person=" + now.name() + " claimed="
                        + now.claimed() + " due-total=" + now.dueTotal() + " overdue-total=" + now.overdueTotal());
            }
        }
        String claimedBefore = claimedTotal(before.figures());
        String dueBefore = dueTotal(before.figures());
        String claimedAfter = claimedTotal(after);
        String dueAfter = dueTotal(after);
        String overdueBefore = overdueTotal(before.figures());
        String overdueAfter = overdueTotal(after);
        if (!Objects.equals(claimedBefore, claimedAfter) || !Objects.equals(dueBefore, dueAfter)
                || !Objects.equals(overdueBefore, overdueAfter)) {
            audit.record("TOTALS sheet=" + sheetId + " by=" + by + " claimed-total=" + claimedAfter + " due-total="
                    + dueAfter + " overdue-total=" + overdueAfter);
        }
    }

    private static String claimedTotal(Map<Long, Figures> figures) {
        return figures.values().stream().map((f) -> new BigDecimal(f.claimed()))
                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add).toPlainString();
    }

    private static String overdueTotal(Map<Long, Figures> figures) {
        return figures.values().stream().map((f) -> new BigDecimal(f.overdueTotal()))
                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add).toPlainString();
    }

    private static String dueTotal(Map<Long, Figures> figures) {
        return figures.values().stream().filter((f) -> !f.dueTotal().equals("n/a"))
                .map((f) -> new BigDecimal(f.dueTotal())).reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add)
                .toPlainString();
    }
}
import { live, useClaims, type ClaimStatus } from '../claims/claims';
import { overdue } from '../overdue/overdue';
import { usePeople } from '../people/people';
import { personDue, sum, useRates } from '../rates/rates';
import { useCap, useFloor, useLate } from '../settings/settings';

// The sheet-wide figures shown in more than one place (the rollups, the summary and the header), worked out once
// here so every place that shows one shows the same value.

/** The statuses claims are counted by. */
export const STATUSES: readonly ClaimStatus[] = ['DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID'];

/** The sheet's due-total: everyone's due-total added up, skipping n/a. */
export function useSheetDueTotal(sheetId: string): string {
  const people = usePeople(sheetId);
  const claims = useClaims(sheetId);
  const rates = useRates(sheetId);
  const late = useLate(sheetId);
  const floor = useFloor(sheetId);
  const cap = useCap(sheetId);
  return sum(
    (people.data ?? []).map((p) =>
      personDue(live(claims.data?.filter((c) => c.personId === p.id) ?? [], [p]), rates.data, p, late, floor, cap),
    ),
  );
}

/** The sheet's overdue count and overdue-total: everyone's added up. */
export function useSheetOverdue(sheetId: string): { count: number; total: string } {
  const people = usePeople(sheetId);
  const claims = useClaims(sheetId);
  const rates = useRates(sheetId);
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);
  const all = (people.data ?? []).map((p) =>
    overdue(live(claims.data?.filter((c) => c.personId === p.id) ?? [], [p]), rates.data, p, late, floor),
  );
  return { count: all.reduce((n, o) => n + o.count, 0), total: sum(all.map((o) => o.total)) };
}

/** How many of the sheet's claims have each status. */
export function useStatusCounts(sheetId: string): (status: ClaimStatus) => number {
  const claims = useClaims(sheetId);
  return (status) => (claims.data ?? []).filter((c) => c.status === status).length;
}
